<?php
require_once dirname(__DIR__).'/config/database.php';
$pdo=conectarBD();$resultados=[];
$ok=static function(string $id,string $prueba,string $detalle='')use(&$resultados):void{$resultados[]=['id'=>$id,'prueba'=>$prueba,'resultado'=>'CUMPLE','detalle'=>$detalle];};
$fail=static function(string $id,string $prueba,string $detalle)use(&$resultados):void{$resultados[]=['id'=>$id,'prueba'=>$prueba,'resultado'=>'FALLA','detalle'=>$detalle];};
$expectError=static function(PDO $pdo,string $savepoint,callable $accion):bool{$pdo->exec("SAVEPOINT $savepoint");try{$accion();$pdo->exec("ROLLBACK TO SAVEPOINT $savepoint");return false;}catch(Throwable){$pdo->exec("ROLLBACK TO SAVEPOINT $savepoint");return true;}};
try{
 $pdo->beginTransaction();
 $agenda=$pdo->query("SELECT h.medico_id,h.dia_semana,h.hora_inicio,h.intervalo_minutos,me.especialidad_id FROM horarios_atencion h JOIN medicos m ON m.id=h.medico_id AND m.activo=TRUE JOIN medicos_especialidades me ON me.medico_id=m.id JOIN especialidades e ON e.id=me.especialidad_id AND e.activo=TRUE WHERE h.activo=TRUE ORDER BY h.id LIMIT 1")->fetch();
 if(!$agenda)throw new RuntimeException('No existe un horario activo para ejecutar las pruebas.');
 $usuario=(int)$pdo->query("SELECT id FROM usuarios WHERE activo=TRUE ORDER BY CASE WHEN rol_id IN (1,2) THEN 0 ELSE 1 END,id LIMIT 1")->fetchColumn();
 $fecha=new DateTimeImmutable('tomorrow');while((int)$fecha->format('N')!==(int)$agenda['dia_semana'])$fecha=$fecha->modify('+1 day');
 $inicio=null;$intervalo=(int)$agenda['intervalo_minutos'];
 for($semana=0;$semana<12&&!$inicio;$semana++){
   $candidata=$fecha->modify('+'.($semana*7).' days')->format('Y-m-d').' '.substr($agenda['hora_inicio'],0,8);
   $fin=(new DateTimeImmutable($candidata))->modify("+$intervalo minutes")->format('Y-m-d H:i:s');
   $s=$pdo->prepare("SELECT NOT EXISTS(SELECT 1 FROM citas WHERE medico_id=:m AND estado IN ('solicitada','confirmada') AND tsrange(inicio,fin,'[)')&&tsrange(:i::timestamp,:f::timestamp,'[)')) AND NOT EXISTS(SELECT 1 FROM bloqueos_horario WHERE medico_id=:m AND tsrange(inicio,fin,'[)')&&tsrange(:i::timestamp,:f::timestamp,'[)'))");$s->execute(['m'=>$agenda['medico_id'],'i'=>$candidata,'f'=>$fin]);if($s->fetchColumn())$inicio=new DateTimeImmutable($candidata);
 }
 if(!$inicio)throw new RuntimeException('No se encontró un bloque libre para la prueba.');$fin=$inicio->modify("+$intervalo minutes");
 $ci='QA-'.bin2hex(random_bytes(6));$s=$pdo->prepare("INSERT INTO pacientes(nombres,apellidos,documento_identidad,activo) VALUES('Prueba','Automática',:ci,TRUE) RETURNING id");$s->execute(['ci'=>$ci]);$paciente=(int)$s->fetchColumn();$ok('P01','Registrar paciente nuevo','Registro creado dentro de transacción reversible.');
 $duplicado=$expectError($pdo,'sp_dup',fn()=>$pdo->prepare("INSERT INTO pacientes(nombres,apellidos,documento_identidad) VALUES('Duplicado','QA',:ci)")->execute(['ci'=>$ci]));$duplicado?$ok('P02','Rechazar CI duplicado','Restricción UNIQUE activa.'):$fail('P02','Rechazar CI duplicado','La base aceptó un CI repetido.');
 $codigo='QA-CITA-'.strtoupper(bin2hex(random_bytes(5)));$s=$pdo->prepare("INSERT INTO citas(codigo_cita,paciente_id,medico_id,especialidad_id,inicio,fin,modalidad,estado,motivo,registrado_por) VALUES(:c,:p,:m,:e,:i,:f,'presencial','solicitada','Prueba automática',:u) RETURNING id");$s->execute(['c'=>$codigo,'p'=>$paciente,'m'=>$agenda['medico_id'],'e'=>$agenda['especialidad_id'],'i'=>$inicio->format('Y-m-d H:i:s'),'f'=>$fin->format('Y-m-d H:i:s'),'u'=>$usuario]);$cita=(int)$s->fetchColumn();$ok('P03','Programar cita disponible',$codigo.' en horario configurado.');
 $superpuesta=$expectError($pdo,'sp_overlap',function()use($pdo,$paciente,$agenda,$inicio,$fin,$usuario){$s=$pdo->prepare("INSERT INTO citas(codigo_cita,paciente_id,medico_id,especialidad_id,inicio,fin,registrado_por) VALUES(:c,:p,:m,:e,:i,:f,:u)");$s->execute(['c'=>'QA-OVER-'.bin2hex(random_bytes(4)),'p'=>$paciente,'m'=>$agenda['medico_id'],'e'=>$agenda['especialidad_id'],'i'=>$inicio->format('Y-m-d H:i:s'),'f'=>$fin->format('Y-m-d H:i:s'),'u'=>$usuario]);});$superpuesta?$ok('P04','Impedir cita superpuesta','Restricción de exclusión PostgreSQL activa.'):$fail('P04','Impedir cita superpuesta','Se aceptó una superposición.');
 $fueraInicio=$inicio->modify('-1 minute');$fueraFin=$fueraInicio->modify("+$intervalo minutes");$fuera=$expectError($pdo,'sp_out',function()use($pdo,$paciente,$agenda,$fueraInicio,$fueraFin,$usuario){$s=$pdo->prepare("INSERT INTO citas(codigo_cita,paciente_id,medico_id,especialidad_id,inicio,fin,registrado_por) VALUES(:c,:p,:m,:e,:i,:f,:u)");$s->execute(['c'=>'QA-OUT-'.bin2hex(random_bytes(4)),'p'=>$paciente,'m'=>$agenda['medico_id'],'e'=>$agenda['especialidad_id'],'i'=>$fueraInicio->format('Y-m-d H:i:s'),'f'=>$fueraFin->format('Y-m-d H:i:s'),'u'=>$usuario]);});$fuera?$ok('P05','Rechazar cita fuera del horario','Trigger validar_cita activo.'):$fail('P05','Rechazar cita fuera del horario','Se aceptó un intervalo inválido.');
 $pdo->prepare("UPDATE citas SET estado='cancelada',motivo_cancelacion='Prueba automática' WHERE id=:id")->execute(['id'=>$cita]);$estado=$pdo->query("SELECT estado FROM citas WHERE id=$cita")->fetchColumn();$hist=(int)$pdo->query("SELECT COUNT(*) FROM historial_citas WHERE cita_id=$cita")->fetchColumn();($estado==='cancelada'&&$hist>=2)?$ok('P06','Cancelar cita y conservar historial',"Estado cancelado; $hist eventos auditados."):$fail('P06','Cancelar cita y conservar historial','No se conservó correctamente.');
 $s=$pdo->prepare("INSERT INTO citas(codigo_cita,paciente_id,medico_id,especialidad_id,inicio,fin,registrado_por) VALUES(:c,:p,:m,:e,:i,:f,:u) RETURNING id");$s->execute(['c'=>'QA-REUSE-'.bin2hex(random_bytes(4)),'p'=>$paciente,'m'=>$agenda['medico_id'],'e'=>$agenda['especialidad_id'],'i'=>$inicio->format('Y-m-d H:i:s'),'f'=>$fin->format('Y-m-d H:i:s'),'u'=>$usuario]);$ok('P06B','Liberar horario cancelado','El mismo bloque volvió a estar disponible.');
 $cantidad=(int)$pdo->query("SELECT COUNT(*) FROM citas WHERE paciente_id=$paciente")->fetchColumn();$cantidad>=2?$ok('P07','Consultar historial del paciente',"Se recuperaron $cantidad citas relacionadas."):$fail('P07','Consultar historial del paciente','Consulta incompleta.');
 $s=$pdo->prepare("SELECT COUNT(*) FROM citas WHERE medico_id=:m AND inicio::date=:f");$s->execute(['m'=>$agenda['medico_id'],'f'=>$inicio->format('Y-m-d')]);$ok('P08','Buscar agenda por médico y fecha',(int)$s->fetchColumn().' resultado(s).');
 $login=file_get_contents(dirname(__DIR__).'/public/procesar_login.php');$helpers=file_get_contents(dirname(__DIR__).'/public/includes/panel_helpers.php');(str_contains($login,'password_verify')&&str_contains($login,'session_regenerate_id')&&str_contains($helpers,"header('Location: login_moderno.php')"))?$ok('P09','Denegar páginas internas sin sesión','Sesión, rol y redirección implementados.'):$fail('P09','Denegar páginas internas sin sesión','Protecciones incompletas.');
 $guardar=file_get_contents(dirname(__DIR__).'/public/guardar_cita.php');(str_contains($guardar,'inicioCitaValido')&&str_contains($guardar,"error=pasado")&&str_contains($guardar,'FILTER_VALIDATE_INT'))?$ok('P10','Rechazar datos inválidos en servidor','Validación de enteros, fecha, hora y pasado presente.'):$fail('P10','Rechazar datos inválidos en servidor','No se localizaron todas las validaciones.');
 $pdo->rollBack();
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$fail('GENERAL','Ejecución de pruebas',$e->getMessage());}
$fallas=count(array_filter($resultados,fn($r)=>$r['resultado']==='FALLA'));echo json_encode(['fecha'=>date(DATE_ATOM),'resultados'=>$resultados,'fallas'=>$fallas],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE),PHP_EOL;exit($fallas?1:0);
